                         onClick={handleConfirmInitSelection} 
                         className="bg-indigo-600 p-3 rounded-full text-white shadow-lg disabled:opacity-50 animate-bounce"
                      >
                          <ArrowRight size={24} />
                      </button>
                   )}
                   {gameState.phase === Phase.RESOURCE_START && isPlayerTurn && (
                       <>
                           <button onClick={() => handleResourceOption('ADD')} className="bg-emerald-600 p-3 rounded-full text-white shadow-lg">
                               <ArrowUpCircle size={24} />
                           </button>
                           <button onClick={() => handleResourceOption('SWAP')} className="bg-amber-600 p-3 rounded-full text-white shadow-lg">
                               <RotateCcw size={24} />
                           </button>
                       </>
                   )}
                   {gameState.phase === Phase.MAIN && isPlayerTurn && (
                       <>
                           {!bottomPlayer.hasAttackedThisTurn && (
                               <button onClick={() => advancePhase(Phase.ATTACK_DECLARE)} className="bg-rose-600 p-3 rounded-full text-white shadow-lg">
                                   <Sword size={24} />
                               </button>
                           )}
                           <button onClick={requestEndTurn} className={`bg-slate-700 p-3 rounded-full text-white shadow-lg ${isEndTurnPulse}`}>
                               <ArrowRight size={24} />
                           </button>
                       </>
                   )}
                   {gameState.phase === Phase.ATTACK_DECLARE && isPlayerTurn && (
                       <button onClick={confirmAttack} className="bg-rose-600 px-4 py-2 rounded-full text-white font-bold shadow-lg animate-pulse">
