                       </button>
                   )}
                   {gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId === bottomPlayer.id && (
                       <button onClick={confirmBlocks} className="bg-blue-600 px-4 py-2 rounded-full text-white font-bold shadow-lg">
                           BLOCK
                       </button>
                   )}
              </div>
          </div>

          {/* Mobile Bottom Bar: Player Info & Hand */}
          <div className="bg-slate-900 border-t border-slate-800 shrink-0 z-30">
