                      <div className="flex items-center gap-1 text-red-500 font-black text-xl" ref={bottomLifeRef}>
                         <Heart size={20} fill="currentColor" /> {bottomPlayer.life}
                      </div>
                  </div>

                  <div className="flex items-center gap-3">
