                             {lesson.title} - Step {(gameState.tutorialStep || 0) + 1}/{lesson.steps.length}
                         </h4>
                         <p className="text-white text-lg font-medium leading-relaxed">
                             {step.message}
                         </p>
                     </div>
                     {step.trigger === 'CLICK_NEXT' && (
