      {explosions.map(e => <Explosion key={e.id} x={e.x} y={e.y} onComplete={() => setExplosions(prev => prev.filter(x => x.id !== e.id))} />)}
      {damageAnim && <DamageOverlay dmg={damageAnim.val} state={damageAnim.state} targetRef={damageAnim.playerId === topPlayer.id ? lifeIconRef : bottomLifeRef} />}
      <svg className="absolute inset-0 z-10 w-full h-full pointer-events-none">{Object.entries(gameState.pendingBlocks).map(([blockerId, attackerId]) => { const blockerEl = document.getElementById(blockerId); const attackerEl = document.getElementById(attackerId); if (blockerEl && attackerEl) { const bRect = blockerEl.getBoundingClientRect(); const aRect = attackerEl.getBoundingClientRect(); return <line key={`${blockerId}-${attackerId}`} x1={bRect.left + bRect.width/2} y1={bRect.top + bRect.height/2} x2={aRect.left + aRect.width/2} y2={aRect.top + aRect.height/2} stroke="#3b82f6" strokeWidth="4" strokeDasharray="0" className="opacity-70"/>; } return null; })}{dragState?.sourceType === 'FIELD' && dragState.currentX && (() => { const startEl = document.getElementById(dragState.instanceId!); if(startEl) { const rect = startEl.getBoundingClientRect(); return <line x1={rect.left + rect.width/2} y1={rect.top + rect.height/2} x2={dragState.currentX} y2={dragState.currentY} stroke="#3b82f6" strokeWidth="4" strokeDasharray="5" className="opacity-70"/>; } })()}</svg>
      {isMobile ? (
          <div className="flex flex-col h-full bg-slate-950 select-none">
          <div className="h-14 bg-slate-900 border-b border-slate-800 flex items-center justify-between px-3 shadow-md z-30 shrink-0"><div className="flex items-center gap-3"><button onClick={() => setShowMenu(true)} className="p-1.5 bg-slate-800 rounded text-slate-400"><Menu size={18} /></button><div className="flex flex-col leading-tight"><span className="text-xs font-bold text-indigo-300">{topPlayer.name}</span><div className="flex items-center gap-2 text-xs text-slate-500" ref={topDeckRef}><span>Deck: {gameState.mode === 'STREET' ? gameState.deck.length : topPlayer.library.length}</span></div></div></div><div className="absolute left-1/2 -translate-x-1/2 flex flex-col items-center"><span className="font-title font-bold text-amber-500 text-sm">TURN {gameState.turnCount}</span><span className="text-[10px] text-slate-400 uppercase tracking-wider">{getPhaseName()}</span></div><div className="flex items-center gap-3" ref={lifeIconRef}><div className="flex items-center gap-1 text-red-400 font-black text-xl"><Heart size={20} fill="currentColor" /> {topPlayer.life}</div>{gameState.mode === 'PRO' && <button onClick={() => setViewingDiscard(topPlayer.id)} className="text-slate-500"><Trash2 size={16} /></button>}</div></div>
          <div id="field-area" className="flex-1 relative bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')] overflow-hidden flex flex-col">
              <button onClick={() => setShowMobileLog(!showMobileLog)} className={`absolute top-2 left-2 z-40 p-2 rounded-full border shadow-lg transition-colors ${showMobileLog ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-slate-900/80 border-slate-700 text-slate-400'}`}>{showMobileLog ? <X size={16} /> : <div className="text-[10px] font-bold">LOG</div>}</button>
              {showMobileLog && <div className="absolute top-12 left-2 right-2 bottom-auto max-h-48 z-40 bg-black/80 backdrop-blur-md border border-slate-700 rounded-lg overflow-y-auto p-2 flex flex-col-reverse gap-1 shadow-2xl">{gameState.logs.map((log, i) => <div key={i} className="text-xs text-slate-300 border-l-2 border-indigo-500 pl-2"><LogRenderer text={log} /></div>)}</div>}
              <div className="flex-1 flex flex-col items-center justify-start py-2 space-y-2 relative"><div className="flex -space-x-6 scale-75 opacity-90 h-12" ref={cpuHandRef}>{topPlayer.hand.map(c => <CardDisplay key={c.id} domId={c.id} card={c} showBack={gameState.mode !== 'SANDBOX'} size="sm" onClick={() => handleCardClick(c, 'HAND', topPlayer.id)} />)}</div>
                  <div className="w-full flex justify-between px-1 items-start gap-1"><div className="flex-1 flex justify-center gap-1 overflow-x-auto px-1 min-h-[80px]"><div className="bg-slate-900/40 p-1 rounded border border-slate-700/50 flex gap-1 min-w-[50px] items-center justify-center">{topPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (<div key={fc.instanceId} className="scale-75 origin-top -mx-2"><CardDisplay domId={fc.instanceId} data-instance-id={fc.instanceId} card={fc.card} isTapped={fc.isTapped} isSummoningSick={fc.isSummoningSick} size="sm" isLunging={gameState.activeCombatCardId === fc.instanceId} damageTaken={gameState.recentDamage[fc.instanceId]} attachedCards={fc.attachedCards} orientation="top" onClick={() => handleCardClick(fc.card, 'FIELD', topPlayer.id, fc.instanceId)}/></div>))}</div><div className="bg-red-900/20 p-1 rounded border border-red-900/30 flex gap-1 min-w-[50px] items-center justify-center">{topPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (<div key={fc.instanceId} className="scale-75 origin-top -mx-2"><CardDisplay domId={fc.instanceId} data-instance-id={fc.instanceId} card={fc.card} isTapped={fc.isTapped} isSummoningSick={fc.isSummoningSick} size="sm" isLunging={gameState.activeCombatCardId === fc.instanceId} damageTaken={gameState.recentDamage[fc.instanceId]} attachedCards={fc.attachedCards} orientation="top" onClick={() => handleCardClick(fc.card, 'FIELD', topPlayer.id, fc.instanceId)}/></div>))}</div></div><div className="flex items-center gap-1 scale-75 origin-top-right shrink-0"><div className="text-[12px] font-bold text-slate-500 bg-slate-900/80 px-1.5 py-0.5 rounded border border-slate-700">{topPlayer.resources.length}</div><div id={`resource-container-${topPlayer.id}`} className="flex flex-col items-center -space-y-10">{topPlayer.resources.map((r, i) => (<div key={r.instanceId} style={{ zIndex: i }} onClick={() => handleCardClick(r.card, 'RESOURCE', topPlayer.id, r.instanceId)}><CardDisplay card={r.card} isTapped={r.isTapped} size="sm" isSummoningSick={r.isSummoningSick} /></div>))}</div></div></div></div>
              <div className="flex-1 flex flex-col justify-end py-2 space-y-2 relative border-t border-slate-800/30">
                  <div className="w-full flex justify-between px-1 items-end mb-2 gap-1">
                       <div className="flex items-center gap-1 scale-75 origin-bottom-left shrink-0 z-20"><div id={`resource-container-${bottomPlayer.id}`} className="flex flex-col items-center -space-y-10">{bottomPlayer.resources.map((r, i) => (<div key={r.instanceId} id={r.instanceId} style={{ zIndex: i }} onClick={() => handleCardClick(r.card, 'RESOURCE', bottomPlayer.id, r.instanceId)}><CardDisplay card={r.card} isTapped={r.isTapped} size="sm" isSummoningSick={r.isSummoningSick} /></div>))}</div><div className="text-[12px] font-bold text-indigo-400 bg-slate-900/80 px-1.5 py-0.5 rounded border border-slate-700">{bottomPlayer.resources.filter(r => !r.isTapped).length}/{bottomPlayer.resources.length}</div></div>
                       <div className="flex-1 flex justify-center gap-1 overflow-x-auto px-1 min-h-[80px]"><div className="bg-slate-900/40 p-1 rounded border border-slate-700/50 flex gap-1 min-w-[50px] items-center justify-center">{bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Black).map(fc => (<div key={fc.instanceId} className="scale-75 origin-bottom -mx-2"><CardDisplay domId={fc.instanceId} data-instance-id={fc.instanceId} card={fc.card} isTapped={fc.isTapped} isSummoningSick={fc.isSummoningSick} size="sm" isAttacking={gameState.pendingAttackers.includes(fc.instanceId)} isBlocking={!!gameState.pendingBlocks[fc.instanceId]} isLunging={gameState.activeCombatCardId === fc.instanceId} damageTaken={gameState.recentDamage[fc.instanceId]} attachedCards={fc.attachedCards} onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)} onMouseDown={(e) => handleDragStart(e, fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)} isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick} orientation="bottom"/></div>))}</div><div className="bg-red-900/20 p-1 rounded border border-red-900/30 flex gap-1 min-w-[50px] items-center justify-center">{bottomPlayer.field.filter(c => getEffectiveColor(c) === Color.Red).map(fc => (<div key={fc.instanceId} className="scale-75 origin-bottom -mx-2"><CardDisplay domId={fc.instanceId} data-instance-id={fc.instanceId} card={fc.card} isTapped={fc.isTapped} isSummoningSick={fc.isSummoningSick} size="sm" isAttacking={gameState.pendingAttackers.includes(fc.instanceId)} isBlocking={!!gameState.pendingBlocks[fc.instanceId]} isLunging={gameState.activeCombatCardId === fc.instanceId} damageTaken={gameState.recentDamage[fc.instanceId]} attachedCards={fc.attachedCards} onClick={() => handleCardClick(fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)} onMouseDown={(e) => handleDragStart(e, fc.card, 'FIELD', bottomPlayer.id, fc.instanceId)} isPlayable={gameState.phase === Phase.ATTACK_DECLARE && !fc.isTapped && !fc.isSummoningSick} orientation="bottom"/></div>))}</div><div className="w-12 shrink-0"></div></div></div>
              </div>
              <div className="absolute bottom-2 right-2 flex flex-col gap-2 z-30">
                   {gameState.phase === Phase.INIT_SELECT && isPlayerTurn && <button disabled={gameState.initSelectedIds.length !== 3} onClick={handleConfirmInitSelection} className="bg-indigo-600 p-3 rounded-full text-white shadow-lg disabled:opacity-50 animate-bounce"><ArrowRight size={24} /></button>}
                   {gameState.phase === Phase.RESOURCE_START && isPlayerTurn && <><button onClick={() => handleResourceOption('ADD')} className="bg-emerald-600 p-3 rounded-full text-white shadow-lg"><ArrowUpCircle size={24} /></button><button onClick={() => handleResourceOption('SWAP')} className="bg-amber-600 p-3 rounded-full text-white shadow-lg"><RotateCcw size={24} /></button></>}
