                   {gameState.phase === Phase.ATTACK_DECLARE && isPlayerTurn && <button onClick={confirmAttack} className="bg-rose-600 px-4 py-2 rounded-full text-white font-bold shadow-lg animate-pulse">CONFIRM</button>}
                   {gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId === bottomPlayer.id && <button onClick={confirmBlocks} className="bg-blue-600 px-4 py-2 rounded-full text-white font-bold shadow-lg">BLOCK</button>}
              </div>
