  };

  const renderSandboxTools = () => {
      const sortedDeck = getSortedDeck();
      const filtered = sortedDeck.filter(c => c.rank.toLowerCase().includes(sandboxSearchTerm.toLowerCase()) || c.suit.toLowerCase().includes(sandboxSearchTerm.toLowerCase()) || `${c.rank}${c.suit}`.toLowerCase().includes(sandboxSearchTerm.toLowerCase()));
      return (
