                  <h1 className="text-6xl md:text-8xl font-black font-title text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 drop-shadow-[0_0_25px_rgba(234,179,8,0.5)] animate-bounce">{gameState.mode === 'TUTORIAL' ? 'LESSON COMPLETE' : 'GAME OVER'}</h1>
