                  <div className="flex items-center justify-center gap-3 bg-slate-800 p-3 rounded-lg"><input type="checkbox" id="menuSort" checked={autoSort} onChange={toggleAutoSort} className="w-5 h-5 accent-indigo-500"/><label htmlFor="menuSort" className="text-slate-300 select-none cursor-pointer font-bold text-sm">Auto-Sort Hand</label></div>
                  <button onClick={() => setShowMenu(false)} className="w-full py-3 bg-slate-700 hover:bg-slate-600 rounded-lg font-bold flex items-center justify-center gap-2"><Play size={18} /> Resume</button>
                  <button onClick={() => setShowResignModal(true)} className="w-full py-3 bg-red-900/50 hover:bg-red-900/80 text-red-200 rounded-lg font-bold flex items-center justify-center gap-2 border border-red-900"><LogOut size={18} /> Resign</button>
                  <button onClick={() => setGameState(null)} className="w-full py-3 bg-slate-800 hover:bg-slate-700 text-slate-400 rounded-lg font-bold flex items-center justify-center gap-2"><ArrowRight size={18} /> Quit to Title</button>
              </div>
          </div>
      )}
      {viewingDiscard !== null && (
          <div className="absolute inset-0 z-[110] flex items-center justify-center bg-black/90 backdrop-blur-md" onClick={() => setViewingDiscard(null)}>
               <div className="relative w-full max-w-4xl p-8 bg-slate-900 border border-slate-700 rounded-xl shadow-2xl max-h-[80vh] flex flex-col" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-between items-center mb-6"><h2 className="text-2xl font-bold font-title text-white flex items-center gap-3"><Trash2 className="text-slate-500" />{viewingDiscard === 'SHARED' ? 'Shared Graveyard' : `${gameState.players[viewingDiscard].name}'s Graveyard`}</h2><button onClick={() => setViewingDiscard(null)} className="p-2 hover:bg-slate-800 rounded-full transition-colors"><X size={24} className="text-slate-400" /></button></div>
                    <div className="flex-1 overflow-y-auto p-4 bg-slate-950/50 rounded-lg border border-slate-800">
                        {discardCards.length === 0 ? <div className="flex flex-col items-center justify-center h-48 text-slate-600 italic">No cards in graveyard.</div> : <div className="flex flex-wrap gap-4 justify-center">{discardCards.map((c, i) => (<div key={i} className="hover:scale-110 transition-transform"><CardDisplay card={c} size="md" /></div>))}</div>}
                    </div>
               </div>
          </div>
      )}
      {specialAnim && <SpecialCardAnimation type={specialAnim.type} card={specialAnim.card} targetRect={specialAnim.targetRect} onComplete={() => setSpecialAnim(null)} />}
      {flyingCards.map(fc => <Flyer key={fc.id} fc={fc} />)}
      {flyingTexts.map(ft => <div key={ft.id} className="fixed z-[70] text-5xl font-black text-red-500 pointer-events-none drop-shadow-md" style={{ left: ft.startX, top: ft.startY, transition: 'all 1s ease-in-out', transform: `translate(${ft.targetX - ft.startX}px, ${ft.targetY - ft.startY}px) scale(0.5)`, opacity: 0, animation: 'fly 1s forwards' }}>{ft.text}<style>{`@keyframes fly { 0% { opacity: 1; } 100% { opacity: 0; } }`}</style></div>)}
      {explosions.map(e => <Explosion key={e.id} x={e.x} y={e.y} onComplete={() => setExplosions(prev => prev.filter(x => x.id !== e.id))} />)}
      {damageAnim && <DamageOverlay dmg={damageAnim.val} state={damageAnim.state} targetRef={damageAnim.playerId === topPlayer.id ? lifeIconRef : bottomLifeRef} />}
      <svg className="absolute inset-0 z-10 w-full h-full pointer-events-none">{Object.entries(gameState.pendingBlocks).map(([blockerId, attackerId]) => { const blockerEl = document.getElementById(blockerId); const attackerEl = document.getElementById(attackerId); if (blockerEl && attackerEl) { const bRect = blockerEl.getBoundingClientRect(); const aRect = attackerEl.getBoundingClientRect(); return <line key={`${blockerId}-${attackerId}`} x1={bRect.left + bRect.width/2} y1={bRect.top + bRect.height/2} x2={aRect.left + aRect.width/2} y2={aRect.top + aRect.height/2} stroke="#3b82f6" strokeWidth="4" strokeDasharray="0" className="opacity-70"/>; } return null; })}{dragState?.sourceType === 'FIELD' && dragState.currentX && (() => { const startEl = document.getElementById(dragState.instanceId!); if(startEl) { const rect = startEl.getBoundingClientRect(); return <line x1={rect.left + rect.width/2} y1={rect.top + rect.height/2} x2={dragState.currentX} y2={dragState.currentY} stroke="#3b82f6" strokeWidth="4" strokeDasharray="5" className="opacity-70"/>; } })()}</svg>
      {isMobile ? (
          <div className="flex flex-col h-full bg-slate-950 select-none">
