export const startTutorialLevel = (lessonId: string): GameState => {
    const p1: PlayerState = {
        id: 0, name: "Student", isCpu: false, life: 20, hand: [], library: [], resources: [], field: [], discard: [], consecutiveDrawFailures: 0, hasAttackedThisTurn: false
    };
    const p2: PlayerState = {
        id: 1, name: "Trainer", isCpu: true, life: 20, hand: [], library: [], resources: [], field: [], discard: [], consecutiveDrawFailures: 0, hasAttackedThisTurn: false
    };

    let hand: Card[] = [];
    let phase = Phase.MAIN;

    // Custom setup based on lesson
    if (lessonId === 'LESSON_1') {
        phase = Phase.INIT_SELECT;
        hand = [
            tc(Rank.Ten, Suit.Spades, 't1_res1'),
            tc(Rank.Nine, Suit.Diamonds, 't1_res2'),
            tc(Rank.Eight, Suit.Clubs, 't1_res3'),
            tc(Rank.Ace, Suit.Hearts, 't1_keep1'),
            tc(Rank.Two, Suit.Spades, 't1_keep2')
        ];
        p1.hand = hand;
    } 
    else if (lessonId === 'LESSON_2') {
        p1.resources = [createFieldCard(tc(Rank.Ten, Suit.Spades, 'r1'), 0), createFieldCard(tc(Rank.Ten, Suit.Spades, 'r2'), 0), createFieldCard(tc(Rank.Ten, Suit.Spades, 'r3'), 0)];
        p1.hand = [tc(Rank.Three, Suit.Spades, 't2_spade3'), tc(Rank.Two, Suit.Hearts, 't2_heart2')];
    }
    // Lessons 3, 4, 5 are set up via setupState in steps

    return {
        mode: 'TUTORIAL',
        deck: [],
        players: [p1, p2],
        turnPlayer: 0,
        startingPlayerId: 0,
        phase,
        turnCount: 1,
        pendingAttackers: [],
        pendingBlocks: {},
        selectedCardId: null,
        activeCombatCardId: null,
        initSelectedIds: [],
        targetMode: 'NONE',
        sourceCardId: null,
        winner: null,
        recentDamage: {},
        logs: ['Tutorial Started'],
        tutorialId: lessonId,
        tutorialStep: 0
    };
};

