  if (isCoinFlipping) {
       const p1 = gameState!.players[0]; const p2 = gameState!.players[1];
       return <CoinFlipOverlay p1Name={p1.name} p2Name={p2.name} onComplete={(winner) => { setGameState(prev => prev ? { ...prev, turnPlayer: winner, startingPlayerId: winner, logs: addLog(prev, `Coin Flip: ${prev.players[winner].name} goes first!`) } : null); setIsCoinFlipping(false); }} />;
