            <style>{highlightCss}</style>
            <div className="absolute bottom-32 left-1/2 -translate-x-1/2 z-[80] w-full max-w-2xl px-4 pointer-events-none">
                 <div className="bg-slate-900/90 border-2 border-emerald-500/50 backdrop-blur-md p-6 rounded-2xl shadow-2xl flex items-start gap-4 pointer-events-auto animate-in slide-in-from-bottom duration-500">
