const SpecialCardAnimation: React.FC<{ type: 'K' | 'Q' | 'J', card: Card, targetRect?: DOMRect, onComplete: () => void }> = ({ type, card, targetRect, onComplete }) => {
    const [style, setStyle] = useState<React.CSSProperties>({
        position: 'fixed',
        left: '50%',
        top: '50%',
        transform: 'translate(-50%, -50%) scale(0.5)',
        opacity: 0,
        zIndex: 200,
        transition: 'all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275)'
    });

    const [label, setLabel] = useState("");
    const [colorClass, setColorClass] = useState("");

    useEffect(() => {
        let animDuration = 1000;

        if (type === 'K') {
            setLabel("EXECUTE");
            setColorClass("text-red-600 drop-shadow-[0_0_10px_rgba(220,38,38,0.8)]");
            animDuration = 1200;
        } else if (type === 'Q') {
            setLabel("SHIFT");
            setColorClass("text-fuchsia-500 drop-shadow-[0_0_10px_rgba(217,70,239,0.8)]");
            animDuration = 1000;
        } else if (type === 'J') {
            setLabel("REINFORCE");
            setColorClass("text-emerald-500 drop-shadow-[0_0_10px_rgba(16,185,129,0.8)]");
            animDuration = 800;
        }

        requestAnimationFrame(() => {
            const destX = targetRect ? targetRect.left + targetRect.width / 2 : window.innerWidth / 2;
            const destY = targetRect ? targetRect.top + targetRect.height / 2 : window.innerHeight / 2;

            const finalLeft = type === 'J' ? '50%' : destX;
            const finalTop = type === 'J' ? '50%' : destY;
            const transform = type === 'J' ? 'translate(-50%, -50%) scale(1.2)' : 'translate(-50%, -50%) scale(1.5)';

            setStyle({
                position: 'fixed',
                left: finalLeft,
                top: finalTop,
                transform: transform,
                opacity: 1,
                zIndex: 200,
                transition: 'all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275)'
            });
        });

        setTimeout(onComplete, animDuration);
    }, []);

    return (
        <div style={style} className="flex flex-col items-center justify-center pointer-events-none">
            <div className={`shadow-[0_0_50px_rgba(255,255,255,0.2)] rounded-lg ${type === 'Q' ? 'animate-pulse' : ''}`}>
                <CardDisplay card={card} size="lg" showBack={false} />
            </div>
            <div className={`mt-4 text-4xl font-black font-title uppercase tracking-widest ${colorClass} animate-bounce`}>
                {label}
            </div>
        </div>
    );
};

const CoinFlipOverlay: React.FC<{ onComplete: (winner: number) => void, p1Name: string, p2Name: string }> = ({ onComplete, p1Name, p2Name }) => {
    const [rotation, setRotation] = useState(0);
    const [resultText, setResultText] = useState("Flipping...");

    useEffect(() => {
        const winner = Math.random() > 0.5 ? 0 : 1;
        const target = 1800 + (winner === 1 ? 180 : 0);

        requestAnimationFrame(() => {
            setRotation(target);
        });

        const spinDuration = 2000;
        const resultDuration = 1500;

        setTimeout(() => {
            setResultText(winner === 0 ? `${p1Name} Goes First!` : `${p2Name} Goes First!`);
            setTimeout(() => {
                onComplete(winner);
            }, resultDuration);
        }, spinDuration);
    }, []);

    return (
        <div className="fixed inset-0 z-[150] bg-slate-900/90 flex flex-col items-center justify-center">
            <div 
                className="relative w-48 h-48 transition-all duration-[2000ms] ease-out"
                style={{ transform: `rotateY(${rotation}deg)`, transformStyle: 'preserve-3d' }}
            >
                 <div className="absolute inset-0 bg-gradient-to-br from-amber-300 to-amber-600 rounded-full border-4 border-amber-700 flex flex-col items-center justify-center backface-hidden shadow-[0_0_50px_rgba(245,158,11,0.5)]" style={{ backfaceVisibility: 'hidden' }}>
                    <User size={48} className="text-amber-900 mb-2" />
                    <span className="font-black text-amber-900 text-3xl drop-shadow-sm">{p1Name}</span>
                 </div>

                 <div className="absolute inset-0 bg-gradient-to-br from-slate-300 to-slate-500 rounded-full border-4 border-slate-700 flex flex-col items-center justify-center backface-hidden shadow-[0_0_50px_rgba(100,116,139,0.5)]" style={{ transform: 'rotateY(180deg)', backfaceVisibility: 'hidden' }}>
                    {p2Name === 'CPU' ? <Cpu size={48} className="text-slate-900 mb-2" /> : <Users size={48} className="text-slate-900 mb-2" />}
                    <span className="font-black text-slate-900 text-3xl drop-shadow-sm">{p2Name}</span>
                 </div>
            </div>

            <div className="mt-16 text-3xl font-bold text-white animate-bounce">
                {resultText}
            </div>
        </div>
    );
};

const Flyer: React.FC<{ fc: FlyingCard }> = ({ fc }) => {
    const [style, setStyle] = useState<React.CSSProperties>({
        left: fc.startX,
        top: fc.startY,
        position: 'fixed',
        zIndex: 100,
        transform: 'translate(0px, 0px) scale(1) rotate(0deg)',
        transition: 'transform 0.6s cubic-bezier(0.2, 0.8, 0.2, 1)',
        pointerEvents: 'none'
    });

    useLayoutEffect(() => {
        const deltaX = fc.targetX - fc.startX;
        const deltaY = fc.targetY - fc.startY;

        requestAnimationFrame(() => {
            setStyle(prev => ({
                ...prev,
                transform: `translate(${deltaX}px, ${deltaY}px) scale(0.6) rotate(360deg)`
            }));
        });
    }, [fc]);

    return (
        <div style={style}>
            <CardDisplay card={fc.card} showBack={true} size="md" />
        </div>
    );
};

interface ExplosionProps { x: number; y: number; onComplete: () => void; }
const Explosion: React.FC<ExplosionProps> = ({ x, y, onComplete }) => {
    useEffect(() => {
        const t = setTimeout(onComplete, 800);
        return () => clearTimeout(t);
    }, [onComplete]);

    return (
        <div 
            className="fixed pointer-events-none z-[150] flex items-center justify-center"
            style={{ left: x, top: y, width: 0, height: 0 }}
        >
            {[...Array(8)].map((_, i) => (
                <div 
                    key={i}
                    className="absolute bg-white border border-slate-300 w-4 h-6 rounded-sm shadow-xl"
                    style={{
                        animation: `shatter-${i} 0.8s ease-out forwards`,
                        transformOrigin: 'center',
                    }}
                />
            ))}
            <div className="absolute w-20 h-20 bg-white rounded-full animate-ping opacity-50" />
            <style>{`
                ${[...Array(8)].map((_, i) => {
                    const angle = (i / 8) * 360;
                    const dist = 60 + Math.random() * 40;
                    return `@keyframes shatter-${i} { 0% { transform: rotate(${angle}deg) translate(0px) rotate(0deg); opacity: 1; } 100% { transform: rotate(${angle}deg) translate(${dist}px) rotate(${Math.random() * 360}deg); opacity: 0; } }`;
                }).join('\n')}
            `}</style>
        </div>
    );
};

const DamageOverlay: React.FC<{ dmg: number, state: 'POP' | 'FLY', targetRef: React.RefObject<HTMLDivElement> }> = ({ dmg, state, targetRef }) => {
    const [style, setStyle] = useState<React.CSSProperties>({
        position: 'fixed',
        top: '50%',
        left: '50%',
        transform: 'translate(-50%, -50%) scale(0)',
        opacity: 0,
        transition: 'all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275)'
    });

    useEffect(() => {
        if (state === 'POP') {
            requestAnimationFrame(() => {
                setStyle({ position: 'fixed', top: '50%', left: '50%', transform: 'translate(-50%, -50%) scale(1.5)', opacity: 1, transition: 'all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275)' });
            });
        } else if (state === 'FLY' && targetRef.current) {
            const rect = targetRef.current.getBoundingClientRect();
            setStyle({ position: 'fixed', top: rect.top + rect.height/2, left: rect.left + rect.width/2, transform: 'translate(-50%, -50%) scale(0.5)', opacity: 0.5, transition: 'all 0.6s ease-in-out' });
        }
    }, [state, targetRef]);

    return (
        <div className="z-[100] pointer-events-none text-red-500 font-black text-8xl drop-shadow-[0_5px_5px_rgba(0,0,0,0.8)] stroke-white" 
             style={{ ...style, WebkitTextStroke: '2px white' } as React.CSSProperties & { WebkitTextStroke?: string }}>
            -{dmg}
        </div>
    );
};

const LogRenderer: React.FC<{ text: string }> = ({ text }) => {
    const parts = text.split(/(\[.*?\])/g);
    return (
        <span>
            {parts.map((part, i) => {
                if (part.startsWith('[') && part.endsWith(']')) {
                    const content = part.slice(1, -1);
                    const isRed = content.includes('♥') || content.includes('♦') || content.includes('Red');
                    return <span key={i} className={`font-bold ${isRed ? 'text-red-400' : 'text-slate-300'}`}>{content}</span>;
                }
                return part;
            })}
        </span>
    );
};

