                            <div className="absolute inset-0 bg-emerald-500/5 rounded-2xl opacity-0 group-hover:opacity-100 transition-opacity"></div>
                            <div className="bg-slate-950 p-3 rounded-full mb-4 ring-1 ring-slate-700 group-hover:ring-emerald-500/50 transition-all shadow-xl group-hover:scale-110">
                                <BookOpen className="w-6 h-6 text-emerald-400 group-hover:text-emerald-300 transition-colors" />
                            </div>
                            <h3 className="text-xl font-bold text-white mb-2 font-title group-hover:text-emerald-300 transition-colors">Tutorial</h3>
                            <div className="h-px w-12 bg-slate-700 my-2 md:my-3 group-hover:bg-emerald-500/50 transition-colors"></div>
                            <p className="text-slate-400 text-xs leading-relaxed">
                                Learn the rules of engagement.
                            </p>
                        </button>
                      </div>
                  ) : menuStep === 'TUTORIAL_SELECT' ? (
                      <div className="w-full max-w-2xl bg-slate-900 border border-slate-700 rounded-2xl p-6 shadow-2xl animate-in zoom-in duration-300">
