                             <div className="flex items-center gap-3">
                                 <button 
                                     onClick={() => setMenuStep('MODE')} 
                                     className="p-2 hover:bg-slate-800 rounded-full text-slate-400 hover:text-white"
                                 >
                                     <RotateCcw size={20} />
                                 </button>
                                 <h2 className="text-2xl font-bold font-title text-emerald-400">Boot Camp</h2>
                             </div>
                             <div className="text-xs font-bold text-slate-500 uppercase tracking-widest">Select Lesson</div>
                          </div>
                          <div className="grid grid-cols-1 gap-3">
                              {TUTORIAL_LESSONS.map((lesson) => {
                                  const isComplete = tutorialProgress.includes(lesson.id);
                                  return (
                                      <button 
                                          key={lesson.id} 
                                          onClick={() => handleTutorialSelect(lesson.id)}
                                          className="flex items-center justify-between p-4 bg-slate-800 hover:bg-slate-700 border border-slate-700 hover:border-emerald-500/30 rounded-xl group transition-all"
                                      >
                                          <div className="flex flex-col items-start">
                                              <div className="font-bold text-lg text-white group-hover:text-emerald-300 transition-colors">{lesson.title}</div>
                                              <div className="text-xs text-slate-400">{lesson.description}</div>
                                          </div>
                                          {isComplete ? (
                                              <CheckCircle className="text-emerald-500" size={24} />
