                                  <div className="text-left">
                                      <div className="font-bold text-lg text-white group-hover:text-purple-200 transition-colors">Spectate</div>
                                      <div className="text-xs text-slate-500 group-hover:text-purple-400/70 transition-colors">CPU vs CPU</div>
                                  </div>
                              </div>
                              <ArrowRight className="text-slate-600 group-hover:text-purple-400 transition-transform group-hover:translate-x-1" />
                          </button>
                      </div>
                  )}
              </div>
          </div>
      );
  }

  if (isCoinFlipping) {
       const p1 = gameState!.players[0]; const p2 = gameState!.players[1];
       return <CoinFlipOverlay p1Name={p1.name} p2Name={p2.name} onComplete={(winner) => { setGameState(prev => prev ? { ...prev, turnPlayer: winner, startingPlayerId: winner, logs: addLog(prev, `Coin Flip: ${prev.players[winner].name} goes first!`) } : null); setIsCoinFlipping(false); }} />;
  }

  const isHotseat = !gameState.players[1].isCpu || gameState.mode === 'SANDBOX';
  const viewPlayerId = isHotseat ? gameState.turnPlayer : 0; 
  const bottomPlayer = gameState.players[viewPlayerId];
  const topPlayer = gameState.players[viewPlayerId === 0 ? 1 : 0];
  const isPlayerTurn = getActiveDecisionPlayerId(gameState) === viewPlayerId;
  const discardCards = viewingDiscard === 'SHARED' ? [...gameState.players[0].discard, ...gameState.players[1].discard] : (typeof viewingDiscard === 'number' ? gameState.players[viewingDiscard].discard : []);

  const activeDecisionPlayerId = getActiveDecisionPlayerId(gameState);
  const isMainPhase = gameState.phase === Phase.MAIN;
  const isEndTurnPulse = isMainPhase && isPlayerTurn && !canDoAnything(gameState) ? 'animate-pulse ring-2 ring-indigo-400' : '';

  const renderTutorialOverlay = () => {
      if (gameState.mode !== 'TUTORIAL' || !gameState.tutorialId) return null;
      const lesson = TUTORIAL_LESSONS.find(l => l.id === gameState.tutorialId);
      const step = lesson?.steps[gameState.tutorialStep || 0];
      if (!lesson || !step) return null;
      const highlightCss = step.highlightIds?.map(id => `[id='${id}'] { box-shadow: 0 0 0 4px #10b981, 0 0 20px rgba(16, 185, 129, 0.6) !important; z-index: 60 !important; position: relative; }`).join(' ') || '';
      return (
          <>
            <style>{highlightCss}</style>
            <div className="absolute bottom-32 left-1/2 -translate-x-1/2 z-[80] w-full max-w-2xl px-4 pointer-events-none">
                 <div className="bg-slate-900/90 border-2 border-emerald-500/50 backdrop-blur-md p-6 rounded-2xl shadow-2xl flex items-start gap-4 pointer-events-auto animate-in slide-in-from-bottom duration-500">
                     <div className="bg-emerald-500/20 p-3 rounded-full shrink-0"><BookOpen className="text-emerald-400" size={32} /></div>
                     <div className="flex-1"><h4 className="text-emerald-400 font-bold uppercase tracking-wider text-xs mb-1">{lesson.title} - Step {(gameState.tutorialStep || 0) + 1}/{lesson.steps.length}</h4><p className="text-white text-lg font-medium leading-relaxed">{step.message}</p></div>
                     {step.trigger === 'CLICK_NEXT' && <button onClick={advanceTutorialStep} className="bg-emerald-600 hover:bg-emerald-500 text-white font-bold px-6 py-3 rounded-xl shadow-lg animate-pulse">Next</button>}
                 </div>
            </div>
          </>
      );
  };

  const renderSandboxTools = () => {
      const sortedDeck = getSortedDeck();
      const filtered = sortedDeck.filter(c => c.rank.toLowerCase().includes(sandboxSearchTerm.toLowerCase()) || c.suit.toLowerCase().includes(sandboxSearchTerm.toLowerCase()) || `${c.rank}${c.suit}`.toLowerCase().includes(sandboxSearchTerm.toLowerCase()));
      return (
          <div className="absolute top-16 right-4 z-[90] w-72 bg-slate-900 border border-slate-700 rounded-xl shadow-2xl flex flex-col overflow-hidden max-h-[80vh]">
               <div className="p-3 bg-slate-800 border-b border-slate-700 flex justify-between items-center"><h3 className="font-bold text-amber-500 flex items-center gap-2"><Edit3 size={16}/> Sandbox Tools</h3><button onClick={() => setSandboxToolsOpen(false)}><X size={16}/></button></div>
               <div className="p-3 space-y-4 overflow-y-auto">
                   <div className="flex gap-2 bg-slate-950 p-2 rounded">
                       <button onClick={() => setGameState(prev => prev ? { ...prev, turnPlayer: prev.turnPlayer === 0 ? 1 : 0 } : null)} className="flex-1 bg-slate-800 hover:bg-slate-700 py-1 rounded text-xs font-bold flex items-center justify-center gap-1"><Eye size={12} /> Switch View</button>
                       <button onClick={() => setShowPlaySetup(true)} className="flex-1 bg-emerald-700 hover:bg-emerald-600 py-1 rounded text-xs font-bold flex items-center justify-center gap-1"><Play size={12} /> Play</button>
                   </div>
                   <div className="space-y-2"><div className="text-xs text-slate-400 font-bold uppercase">Life Totals</div>
                       {gameState.players.map(p => (
                           <div key={p.id} className="flex justify-between items-center bg-slate-800 p-2 rounded"><span className="text-xs font-bold w-20 truncate">{p.name}</span><div className="flex items-center gap-2">
                                   <button onClick={() => setGameState(prev => { if(!prev) return null; const ps = [...prev.players]; ps[p.id].life = Math.max(0, ps[p.id].life - 1); return { ...prev, players: ps }; })} className="p-1 hover:bg-slate-700 rounded"><Minus size={12}/></button>
                                   <span className="text-sm font-bold w-6 text-center">{p.life}</span>
                                   <button onClick={() => setGameState(prev => { if(!prev) return null; const ps = [...prev.players]; ps[p.id].life += 1; return { ...prev, players: ps }; })} className="p-1 hover:bg-slate-700 rounded"><Plus size={12}/></button>
                               </div></div>))}
                   </div>
                   <div className="space-y-2"><div className="text-xs text-slate-400 font-bold uppercase">Spawn Card</div><div className="relative"><Search className="absolute left-2 top-2 text-slate-500" size={14}/><input className="w-full bg-slate-950 border border-slate-700 rounded pl-8 py-1.5 text-xs focus:outline-none focus:border-amber-500" placeholder="Search" value={sandboxSearchTerm} onChange={e => setSandboxSearchTerm(e.target.value)}/></div>
                       <div className="flex gap-1 text-[10px] font-bold"><button onClick={() => setSandboxTargetPlayer(0)} className={`flex-1 py-1 rounded ${sandboxTargetPlayer === 0 ? 'bg-indigo-600' : 'bg-slate-800'}`}>P1</button><button onClick={() => setSandboxTargetPlayer(1)} className={`flex-1 py-1 rounded ${sandboxTargetPlayer === 1 ? 'bg-rose-600' : 'bg-slate-800'}`}>P2</button></div>
                       <div className="grid grid-cols-4 gap-2 max-h-48 overflow-y-auto p-1 bg-slate-950 rounded border border-slate-800">{filtered.map(c => (<div key={c.id} onClick={() => setSelectedSandboxCard(c)} className={`cursor-pointer transition-transform hover:scale-105 ${selectedSandboxCard?.id === c.id ? 'ring-2 ring-amber-500 rounded' : ''}`}><CardDisplay card={c} size="sm" /></div>))}</div>
                       <div className="grid grid-cols-3 gap-1"><button disabled={!selectedSandboxCard} onClick={() => spawnCard(selectedSandboxCard!, 'HAND', sandboxTargetPlayer)} className="bg-slate-700 hover:bg-slate-600 disabled:opacity-50 py-1 rounded text-[10px] font-bold">Add Hand</button><button disabled={!selectedSandboxCard} onClick={() => spawnCard(selectedSandboxCard!, 'FIELD', sandboxTargetPlayer)} className="bg-slate-700 hover:bg-slate-600 disabled:opacity-50 py-1 rounded text-[10px] font-bold">Add Field</button><button disabled={!selectedSandboxCard} onClick={() => spawnCard(selectedSandboxCard!, 'RESOURCE', sandboxTargetPlayer)} className="bg-slate-700 hover:bg-slate-600 disabled:opacity-50 py-1 rounded text-[10px] font-bold">Add Res</button></div>
                   </div>
               </div>
          </div>
      );
  };

  return (
    <div className="flex flex-col h-screen w-full bg-slate-950 text-slate-100 font-sans select-none" ref={containerRef} onMouseMove={(e) => { if (dragState) setDragState(prev => prev ? { ...prev, currentX: e.clientX, currentY: e.clientY } : null); }} onMouseUp={(e) => { if (dragState) { handleDrop(e.nativeEvent, dragState); setDragState(null); } }}>
      {gameState.isSandboxRun && <div className="absolute top-16 left-4 z-50 animate-in fade-in slide-in-from-top"><button onClick={returnToSandbox} className="bg-amber-600 hover:bg-amber-500 text-white px-4 py-2 rounded-lg font-bold shadow-lg flex items-center gap-2"><RotateCcw size={18}/> Return to Sandbox</button></div>}
      {renderTutorialOverlay()}
      {showPlaySetup && (
          <div className="absolute inset-0 z-[100] bg-black/80 flex items-center justify-center backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 w-80">
                  <h3 className="text-xl font-bold mb-4 flex items-center gap-2"><Play size={20} className="text-emerald-400"/> Play Scenario</h3>
                  <div className="space-y-3"><button onClick={() => startPlayFromHere(true)} className="w-full bg-slate-800 hover:bg-emerald-900/30 border border-slate-700 hover:border-emerald-500/50 p-3 rounded text-left font-bold flex items-center gap-2"><Cpu size={18}/> Vs CPU</button><button onClick={() => startPlayFromHere(false)} className="w-full bg-slate-800 hover:bg-amber-900/30 border border-slate-700 hover:border-amber-500/50 p-3 rounded text-left font-bold flex items-center gap-2"><Users size={18}/> Hotseat</button></div>
                  <button onClick={() => setShowPlaySetup(false)} className="mt-4 text-slate-500 text-sm hover:text-white">Cancel</button>
              </div>
          </div>
      )}
      {cardActionTarget && (
          <div className="absolute inset-0 z-[100] bg-black/50 flex items-center justify-center" onClick={() => setCardActionTarget(null)}>
              <div className="bg-slate-900 p-4 rounded-xl border border-slate-700 shadow-2xl transform scale-100 transition-transform" onClick={e => e.stopPropagation()}>
                  <div className="flex justify-center mb-4"><CardDisplay card={cardActionTarget.card} size="lg" /></div>
                  <div className="flex gap-2 justify-center">{cardActionTarget.loc !== 'HAND' && <button onClick={() => executeCardAction('TAP')} className="bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-2 rounded font-bold flex items-center gap-2"><RotateCcw size={16}/> Tap/Untap</button>}<button onClick={() => executeCardAction('DELETE')} className="bg-red-600 hover:bg-red-500 text-white px-4 py-2 rounded font-bold flex items-center gap-2"><Trash2 size={16}/> Remove</button></div>
              </div>
          </div>
      )}
      {gameState.mode === 'SANDBOX' && !gameState.isSandboxRun && !sandboxToolsOpen && <button onClick={() => setSandboxToolsOpen(true)} className="absolute top-20 right-4 z-50 bg-slate-800 p-3 rounded-full border border-slate-600 shadow-xl hover:bg-slate-700 text-amber-400"><Edit3 size={24} /></button>}
      {sandboxToolsOpen && renderSandboxTools()}
      {gameState.phase === Phase.GAME_OVER && (
          <div className="absolute inset-0 z-[120] flex items-center justify-center bg-black/95 backdrop-blur-md animate-in fade-in duration-1000 overflow-hidden">
              <Confetti />
              <div className="text-center space-y-6 relative z-[130]">
                  <h1 className="text-6xl md:text-8xl font-black font-title text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 drop-shadow-[0_0_25px_rgba(234,179,8,0.5)] animate-bounce">{gameState.mode === 'TUTORIAL' ? 'LESSON COMPLETE' : 'GAME OVER'}</h1>
                  <h2 className="text-3xl font-bold text-white drop-shadow-md">{gameState.mode === 'TUTORIAL' ? 'You have mastered this concept!' : (gameState.winner !== null ? `${gameState.players[gameState.winner].name} Wins!` : "It's a Draw!")}</h2>
                  <div className="flex gap-4 justify-center mt-8"><button onClick={() => { setGameState(null); if(gameState.mode === 'TUTORIAL') setMenuStep('TUTORIAL_SELECT'); }} className="px-8 py-3 bg-indigo-600 hover:bg-indigo-500 rounded-lg font-bold text-xl shadow-lg shadow-indigo-500/30 transform transition-all hover:scale-105 active:scale-95">{gameState.mode === 'TUTORIAL' ? 'Next Lesson' : 'Rematch / Menu'}</button></div>
              </div>
          </div>
      )}
      {showEndTurnModal && (
          <div className="absolute inset-0 z-[80] flex items-center justify-center bg-black/80 backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 shadow-2xl max-w-sm w-full animate-in zoom-in duration-200">
                  <h3 className="text-xl font-bold font-title text-amber-500 mb-2">End Turn?</h3>
                  <p className="text-slate-400 mb-6">Are you sure you want to pass the turn?</p>
                  <div className="flex gap-3 justify-end"><button onClick={() => setShowEndTurnModal(false)} className="px-4 py-2 bg-slate-800 rounded font-bold hover:bg-slate-700">Cancel</button><button onClick={confirmEndTurn} className="px-4 py-2 bg-indigo-600 rounded font-bold hover:bg-indigo-500">Confirm</button></div>
              </div>
          </div>
      )}
      {showResignModal && (
          <div className="absolute inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm">
              <div className="bg-slate-900 p-6 rounded-xl border border-slate-700 shadow-2xl max-w-sm w-full animate-in zoom-in duration-200 border-red-900/50">
                  <h3 className="text-xl font-bold font-title text-red-500 mb-2">Resign Game?</h3>
                  <p className="text-slate-400 mb-6">You will forfeit the match. Are you sure?</p>
                  <div className="flex gap-3 justify-end"><button onClick={() => setShowResignModal(false)} className="px-4 py-2 bg-slate-800 rounded font-bold hover:bg-slate-700">Cancel</button><button onClick={handleResign} className="px-4 py-2 bg-red-600 rounded font-bold hover:bg-red-500">Resign</button></div>
              </div>
          </div>
      )}
      {showMenu && (
          <div className="absolute inset-0 z-[90] flex items-center justify-center bg-black/90 backdrop-blur-md">
              <div className="bg-slate-900 p-8 rounded-2xl border border-slate-700 shadow-2xl w-80 text-center animate-in zoom-in duration-200 space-y-4">
                  <h2 className="text-2xl font-bold font-title text-white mb-6">PAUSED</h2>
                  <div className="flex items-center justify-center gap-3 bg-slate-800 p-3 rounded-lg"><input type="checkbox" id="menuSort" checked={autoSort} onChange={toggleAutoSort} className="w-5 h-5 accent-indigo-500"/><label htmlFor="menuSort" className="text-slate-300 select-none cursor-pointer font-bold text-sm">Auto-Sort Hand</label></div>
                  <button onClick={() => setShowMenu(false)} className="w-full py-3 bg-slate-700 hover:bg-slate-600 rounded-lg font-bold flex items-center justify-center gap-2"><Play size={18} /> Resume</button>
                  <button onClick={() => setShowResignModal(true)} className="w-full py-3 bg-red-900/50 hover:bg-red-900/80 text-red-200 rounded-lg font-bold flex items-center justify-center gap-2 border border-red-900"><LogOut size={18} /> Resign</button>
                  <button onClick={() => setGameState(null)} className="w-full py-3 bg-slate-800 hover:bg-slate-700 text-slate-400 rounded-lg font-bold flex items-center justify-center gap-2"><ArrowRight size={18} /> Quit to Title</button>
              </div>
          </div>
      )}
      {viewingDiscard !== null && (
          <div className="absolute inset-0 z-[110] flex items-center justify-center bg-black/90 backdrop-blur-md" onClick={() => setViewingDiscard(null)}>
               <div className="relative w-full max-w-4xl p-8 bg-slate-900 border border-slate-700 rounded-xl shadow-2xl max-h-[80vh] flex flex-col" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-between items-center mb-6"><h2 className="text-2xl font-bold font-title text-white flex items-center gap-3"><Trash2 className="text-slate-500" />{viewingDiscard === 'SHARED' ? 'Shared Graveyard' : `${gameState.players[viewingDiscard].name}'s Graveyard`}</h2><button onClick={() => setViewingDiscard(null)} className="p-2 hover:bg-slate-800 rounded-full transition-colors"><X size={24} className="text-slate-400" /></button></div>
                    <div className="flex-1 overflow-y-auto p-4 bg-slate-950/50 rounded-lg border border-slate-800">
                        {discardCards.length === 0 ? <div className="flex flex-col items-center justify-center h-48 text-slate-600 italic">No cards in graveyard.</div> : <div className="flex flex-wrap gap-4 justify-center">{discardCards.map((c, i) => (<div key={i} className="hover:scale-110 transition-transform"><CardDisplay card={c} size="md" /></div>))}</div>}
                    </div>
               </div>
          </div>
      )}
