              <div className="flex flex-col gap-2"><div className="text-xs text-slate-500 uppercase font-bold tracking-wider" ref={bottomDeckRef}>Deck: <span className="text-white text-lg ml-1">{gameState.mode === 'STREET' ? gameState.deck.length : bottomPlayer.library.length}</span></div><button onClick={() => setViewingDiscard(gameState.mode === 'STREET' ? 'SHARED' : bottomPlayer.id)} className="flex items-center justify-center gap-2 bg-slate-800 hover:bg-slate-700 py-1.5 rounded text-xs text-slate-400 font-bold transition-colors border border-slate-700 w-full"><Trash2 size={14} /> {gameState.mode === 'STREET' ? 'Shared Graveyard' : 'Graveyard'} <span className="ml-auto bg-slate-900 px-1.5 rounded">{gameState.mode === 'STREET' ? gameState.players[0].discard.length + gameState.players[1].discard.length : bottomPlayer.discard.length}</span></button></div>
          </div>
          <div className="flex-1 p-4 bg-slate-800/50 flex flex-col items-center justify-center relative shadow-inner min-w-0" ref={handRef}>
               <div className="absolute top-2 text-[10px] uppercase font-bold text-slate-500 tracking-widest">Hand</div>
               <div className="flex -space-x-4 pt-4 px-8 pb-2 overflow-visible">
                   {bottomPlayer.hand.map((c) => {
                       const isSelected = gameState.phase === Phase.INIT_SELECT && gameState.initSelectedIds.includes(c.id);
                       let hasValidTarget = true;
                       if (c.rank === 'K') hasValidTarget = topPlayer.field.some(f => getEffectiveColor(f) === c.baseColor);
                       if (c.rank === 'Q') hasValidTarget = topPlayer.field.length > 0 || bottomPlayer.field.length > 0;
                       const isPlayable = isMainPhase && isPlayerTurn && bottomPlayer.resources.filter(r => !r.isTapped).length >= c.cost && hasValidTarget;
                       return (<div key={c.id} id={c.id} className={`transition-all hover:-translate-y-4 hover:z-20 ${isSelected ? '-translate-y-4 z-10' : ''}`}><CardDisplay card={c} onClick={() => handleCardClick(c, 'HAND', bottomPlayer.id)} onMouseDown={(e) => handleDragStart(e, c, 'HAND', bottomPlayer.id)} isPlayable={isPlayable} isSelected={isSelected} isDragging={dragState?.cardId === c.id}/></div>);
                   })}
               </div>
          </div>
          <div className="w-64 bg-slate-900 border-l border-slate-800 p-4 flex flex-col gap-3 shrink-0">
              <div className="text-center text-xs font-bold text-slate-500 uppercase mb-2">Actions</div>
              <div className="flex-1 grid grid-cols-2 gap-2 content-start">
                  {gameState.phase === Phase.INIT_SELECT && isPlayerTurn && <button disabled={gameState.initSelectedIds.length !== 3} onClick={handleConfirmInitSelection} className="col-span-2 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 text-white font-bold rounded shadow-lg h-12">Confirm ({gameState.initSelectedIds.length}/3)</button>}
                  {gameState.phase === Phase.RESOURCE_START && isPlayerTurn && <><button onClick={() => handleResourceOption('ADD')} className="bg-emerald-600 hover:bg-emerald-500 text-white rounded font-bold text-sm flex flex-col items-center justify-center p-1 h-16 transition-transform active:scale-95"><ArrowUpCircle size={20} className="mb-1"/> Add & Draw</button><button onClick={() => handleResourceOption('SWAP')} className="bg-amber-600 hover:bg-amber-500 text-white rounded font-bold text-sm flex flex-col items-center justify-center p-1 h-16 transition-transform active:scale-95"><RotateCcw size={20} className="mb-1"/> Swap Res</button></>}
                  {gameState.phase === Phase.RESOURCE_ADD_SELECT && <div className="col-span-2 text-center text-xs text-emerald-400 animate-pulse font-bold flex items-center justify-center border border-emerald-900 rounded bg-emerald-900/20 h-12">Select card to Add</div>}
                  {gameState.phase === Phase.RESOURCE_SWAP_SELECT_PILE && <div className="col-span-2 text-center text-xs text-amber-400 animate-pulse font-bold flex items-center justify-center border border-amber-900 rounded bg-amber-900/20 h-12">Select Resource to Swap</div>}
                  {gameState.phase === Phase.MAIN && isPlayerTurn && <><button disabled={bottomPlayer.hasAttackedThisTurn} onClick={() => advancePhase(Phase.ATTACK_DECLARE)} className="col-span-2 bg-rose-600 hover:bg-rose-500 disabled:opacity-50 text-white font-bold rounded flex items-center justify-center gap-2 h-10 transition-transform active:scale-95"><Sword size={18} /> Attack Phase</button><button onClick={requestEndTurn} className={`col-span-2 bg-slate-700 hover:bg-slate-600 text-white font-bold rounded h-10 transition-transform active:scale-95 ${isEndTurnPulse}`}>End Turn</button></>}
                  {gameState.phase === Phase.ATTACK_DECLARE && isPlayerTurn && <button onClick={confirmAttack} className="col-span-2 bg-rose-600 hover:bg-rose-500 text-white font-bold rounded animate-pulse shadow-lg shadow-rose-900/50 h-12">Confirm Attackers</button>}
                  {gameState.phase === Phase.BLOCK_DECLARE && activeDecisionPlayerId === 0 && <button onClick={confirmBlocks} className="col-span-2 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded shadow-lg shadow-blue-900/50 h-12">Confirm Blocks</button>}
                  {gameState.players[activeDecisionPlayerId].isCpu && gameState.phase !== Phase.INIT_SELECT && <div className="col-span-2 flex flex-col items-center justify-center h-full gap-2"><div className="w-6 h-6 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin"></div><span className="text-xs text-indigo-400 font-bold animate-pulse">CPU Thinking...</span></div>}
              </div>
          </div>
      </div>
      <div className="absolute top-20 left-4 w-72 z-40 bottom-60 overflow-y-auto space-y-1 pointer-events-auto pr-2 scrollbar-thin scrollbar-thumb-slate-700 scrollbar-track-transparent flex flex-col-reverse">
          {gameState.logs.map((log, i) => (<div key={i} className="bg-black/70 border-l-4 border-indigo-500 text-slate-200 text-xs p-2 rounded-r shadow-lg backdrop-blur animate-in slide-in-from-left fade-in shrink-0"><LogRenderer text={String(log)} /></div>))}
      </div>
      </>
      )}
    </div>
  );
};

export default App;
